<template><view class="onboarding-page ld-page"><view class="onboarding-hero"><view class="hero-icon"><PrototypeIcon name="task" tone="white" :size="48"/></view><view><text class="hero-title">入驻申请进度</text><text class="hero-caption">每一步进展，都清晰可见</text></view></view><view class="onboarding-content"><view v-if="loading" class="loading-state">正在加载…</view><template v-if="item"><view class="white-group"><view class="organization-row"><view class="organization-icon"><PrototypeIcon name="school" :size="44"/></view><view class="row-copy"><text class="row-title">{{item.name}}</text><text class="row-caption">提交于 {{item.createdAt.replace('T',' ').slice(0,16)}}</text></view><text :class="['status-tag','status-'+item.status.toLowerCase()]">{{applicationStatus[item.status]}}</text></view></view><view class="white-group timeline-card"><view class="timeline-step complete"><view class="timeline-dot"><PrototypeIcon name="check" :size="34"/></view><view><text class="row-title">提交申请</text><text class="row-caption">{{item.createdAt.replace('T',' ').slice(0,19)}}</text></view></view><view :class="['timeline-step',{complete:item.status==='APPROVED'}]"><view class="timeline-dot"><PrototypeIcon :name="item.status==='APPROVED'?'check':'clock'" :size="34"/></view><view><text class="row-title">资料审核</text><text class="row-caption">{{item.status==='PENDING'?'申请已提交，等待审核':item.status==='WITHDRAWN'?'申请已撤回，可修改后重新提交':item.status==='REJECTED'?'资料审核未通过':'审核已通过，组织已创建'}}</text></view></view></view><view class="white-group form-group"><text class="form-section">联系信息</text><view class="detail-line"><text>联系人</text><text>{{item.contactName}}</text></view><view class="detail-line"><text>{{item.email?'邮箱':'手机号'}}</text><text>{{item.email||item.mobile||'未填写'}}</text></view></view><view v-if="item.rejectionReason" class="rejection-card"><text class="row-title">驳回原因</text><text>{{item.rejectionReason}}</text></view><view class="bottom-actions"><button v-if="item.status==='PENDING'" class="outline-action" :disabled="busy" :loading="busy" @tap="withdraw">撤回申请</button><button v-if="item.status==='REJECTED'||item.status==='WITHDRAWN'" class="primary-action" @tap="edit">修改并重新提交</button><button v-if="item.status==='APPROVED'" class="primary-action" @tap="organizations">进入我的组织</button></view></template><view v-if="error" class="error-card"><text>{{error}}</text><button @tap="load">重试</button></view></view></view></template>
<script setup lang="ts">
import PrototypeIcon from '@/components/PrototypeIcon.vue';
import {ref} from 'vue';
import {onLoad,onShow} from '@dcloudio/uni-app';
import {onboardingApi,applicationStatus,type OrganizationApplication} from '@/api/organization-onboarding';
import {onboardingIdentity,resolveOnboardingSession,onboardingUrl,type OnboardingIdentity} from '@/session/onboarding-session';
const identity=ref<OnboardingIdentity|null>(null),id=ref(''),item=ref<OrganizationApplication|null>(null),loading=ref(true),busy=ref(false),error=ref('');
onLoad(options=>{identity.value=onboardingIdentity(options?.identity);id.value=options?.id||'';});onShow(load);
async function load(){const session=await resolveOnboardingSession(identity.value);if(!session||!id.value){loading.value=false;error.value='请从入驻进度进入申请详情';return;}loading.value=true;error.value='';try{item.value=await onboardingApi.application(session.accessToken,id.value);}catch(e){error.value=e instanceof Error?e.message:'加载失败';}finally{loading.value=false;}}
async function withdraw(){const session=await resolveOnboardingSession(identity.value);if(!session||!item.value||busy.value)return;const confirmation=await uni.showModal({title:'撤回申请',content:'撤回后可修改并重新提交。'});if(!confirmation.confirm)return;busy.value=true;error.value='';try{item.value=await onboardingApi.withdraw(session.accessToken,item.value);}catch(e){error.value=e instanceof Error?e.message:'撤回失败';}finally{busy.value=false;}}
function edit(){if(identity.value&&item.value)uni.navigateTo({url:onboardingUrl('organization-onboarding',identity.value,`&kind=institution&applicationId=${encodeURIComponent(item.value.id)}`)});}
function organizations(){if(identity.value)uni.navigateTo({url:onboardingUrl('my-organizations',identity.value)});}
</script>
<style lang="scss" scoped>
@import '@/styles/onboarding-prototype.scss';
.onboarding-page{background:#f5f9f3;padding-bottom:55rpx;}.onboarding-hero{background:transparent;color:#183d2d;min-height:100rpx;padding:24rpx 30rpx;margin:0;box-shadow:none;border-radius:0;justify-content:center;}.hero-icon,.hero-caption{display:none;}.hero-title{font-size:34rpx;color:#183d2d;}.hero-tool{position:absolute;right:28rpx;background:#176c51;border-radius:50%;}.onboarding-content{padding:20rpx 28rpx;}.white-group{background:#fff;border:0;border-radius:26rpx;box-shadow:none;margin-bottom:24rpx;}.form-group{padding:28rpx;}.form-section{font-size:28rpx;margin-bottom:22rpx;}.form-label{font-size:26rpx;margin:22rpx 0 12rpx;}.form-group input,.picker-row{background:#fafcfb;border:1rpx solid #e0e8e2;border-radius:16rpx;min-height:82rpx;padding:16rpx 20rpx;font-size:26rpx;box-sizing:border-box;}.primary-action{background:linear-gradient(110deg,#176b53,#0a5b40);border-radius:18rpx;font-size:30rpx;}.outline-action,.outline-small{border:1rpx solid #247b5b;color:#1a6c50;border-radius:16rpx;}.organization-row,.application-row{padding:24rpx;gap:20rpx;}.organization-icon{background:#e9f5ed;border-radius:16rpx;}.row-title{font-size:28rpx;}.row-caption{font-size:23rpx;}.row-tags text{background:#e8f2ec;color:#32705b;}.step-track{margin:0 0 28rpx;font-size:23rpx;}.timeline-card{padding:30rpx;}.timeline-step{padding:20rpx 0;}.timeline-dot{width:42rpx;height:42rpx;border-radius:50%;}.timeline-step.complete .timeline-dot{background:#167b54;color:white;}.rejection-card{background:#fff0ef;border-radius:24rpx;color:#974d49;padding:28rpx;}.process-note{background:#fff4df;border-radius:20rpx;padding:22rpx;}.section-title{font-size:29rpx;}
</style>
